"use strict";
// A typed package scriptc compiles natively that requires pump's shape.
const pump = require("pumplike");
const once = require("oncelike");

exports.pack = function pack(sizes) {
  let reported = 0;
  const report = once((n) => {
    reported = n;
  });
  const total = pump(...sizes, report);
  return `${total}/${reported}`;
};
